BOOL FrtCmd_132(FrontierScriptContext *ctx, s32 arg1) {
    FieldFrontierDTO *fieldData = Frontier_GetLaunchArgs(ctx->frontierSystem->frontier);

    u16 functionIndex = FrontierScriptContext_ReadHalfWord(ctx);
    u16 functionArgument = FrontierScript_ReadVar(ctx);
    u16 *destVar = FrontierScript_ReadVarPtr(ctx);
    BattleTower *battleTower = Frontier_GetData(ctx->frontierSystem->frontier);

    switch (functionIndex) {
    case BT_FUNC_RESET_SYSTEM:
        ResetSystem();
        break;
    case BT_FUNC_UNK_46:
        *destVar = FrontierFieldSystem_AwardTowerBattlePoints(battleTower);
        GameStats_Add(Save_GameStats_Get(fieldData->saveData), (enum GameRecord)69, *destVar);
        break;
    case BT_FUNC_GET_PARTNER_PARAM:
        *destVar = ov80_0223558C(battleTower, functionArgument);
        break;
    case BT_FUNC_GET_NEXT_OPPONENT_NUM:
        *destVar = FrontierFieldSystem_GetFrontierBattleNumber(battleTower);
        break;
    case BT_FUNC_INCREMENT_CURRENT_BATTLE:
        *destVar = ov80_022358C4(battleTower);
        break;
    case BT_FUNC_HAS_DEFEATED_SEVEN_TRAINERS:
        *destVar = FrontierFieldSystem_0204AC7C(battleTower);
        break;
    case BT_FUNC_GET_CURRENT_STREAK:
        *destVar = ov80_022358E8(battleTower);
        break;
    case BT_FUNC_GET_CHALLENGE_MODE:
        *destVar = FrontierFieldSystem_GetBattleTowerMode(battleTower);
        break;
    case BT_FUNC_SET_OPPONENT_TEAMS:
        ov80_022357B4(battleTower, fieldData->saveData);
        break;
    case BT_FUNC_GET_OPPONENT_OBJECT_ID:
        *destVar = ov80_02235898(battleTower, functionArgument);
        break;
    case BT_FUNC_SET_BEAT_PALMER:
        ov80_022358B0(battleTower, functionArgument);
        break;
    case BT_FUNC_UPDATE_GAME_RECORDS:
        FrontierFieldSystem_0204AD04(battleTower, fieldData->saveData);
        break;
    case BT_FUNC_UPDATE_GAME_RECORDS_AND_JOURNAL:
        FrontierFieldSystem_0204AE20(battleTower, fieldData->saveData);
        break;
    case BT_FUNC_QUICKSAVE:
        FrontierFieldSystem_0204AF2C(battleTower);
        break;
    case BT_FUNC_CLEAR_BUFFER:
        MI_CpuClear8(battleTower->commBuffer, 70);
        break;
    case BT_FUNC_SET_UNUSED_FLAG:
        battleTower->unk_8D6 = 1;
        break;
    case BT_FUNC_CHECK_IS_NULL:
        if (battleTower == NULL) {
            *destVar = TRUE;
        } else {
            *destVar = FALSE;
        }
        break;
    default:
        GF_ASSERT(FALSE);
        break;
    }

    return FALSE;
}
